import pathlib
import sys

for path in sorted(pathlib.Path(sys.argv[1]).rglob("*.py")):
    text = path.read_text()
    if "\t" in text:
        print(f"warning: {path.as_posix()}: tab character", file=sys.stderr)
    if len(text.splitlines()) > 3:
        print(f"warning: {path.as_posix()}: more than 3 lines", file=sys.stderr)
    print(f"checked {path.as_posix()}")
